/* cppi::30724e3a6efeb6e10e84adaf2acd99dfae0568c93a5104c67e2d0ee1c6c3cba0 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-12' and end_date = '2025-05-12')
and start_date = '2025-05-12' and end_date = '2025-05-12'

